package java.util;
import java.util.function.*; public interface Map<K,V> { int size(); boolean isEmpty(); boolean containsKey(Object k); boolean containsValue(Object v); V get(Object k); V put(K k,V v); V remove(Object k); void putAll(Map<? extends K,? extends V> m); void clear(); Set<K> keySet(); Collection<V> values(); Set<Entry<K,V>> entrySet(); interface Entry<K,V> { K getKey(); V getValue(); V setValue(V v); boolean equals(Object o); int hashCode(); static <K extends Comparable<? super K>,V> Comparator<Entry<K,V>> comparingByKey(){return new Comparator<Entry<K,V>>(){public int compare(Entry<K,V> a,Entry<K,V> b){return a.getKey().compareTo(b.getKey());}};} static <K,V extends Comparable<? super V>> Comparator<Entry<K,V>> comparingByValue(){return new Comparator<Entry<K,V>>(){public int compare(Entry<K,V> a,Entry<K,V> b){return a.getValue().compareTo(b.getValue());}};} static <K,V> Comparator<Entry<K,V>> comparingByKey(Comparator<? super K> c){return new Comparator<Entry<K,V>>(){public int compare(Entry<K,V> a,Entry<K,V> b){return c.compare(a.getKey(),b.getKey());}};} static <K,V> Comparator<Entry<K,V>> comparingByValue(Comparator<? super V> c){return new Comparator<Entry<K,V>>(){public int compare(Entry<K,V> a,Entry<K,V> b){return c.compare(a.getValue(),b.getValue());}};} } default V getOrDefault(Object k,V d){V v=get(k);return v!=null||containsKey(k)?v:d;} default V putIfAbsent(K k,V v){V x=get(k);if(x==null)put(k,v);return x;} default boolean remove(Object k,Object v){if(!Objects.equals(get(k),v)||(v==null&&!containsKey(k)))return false;remove(k);return true;} default boolean replace(K k,V old,V v){if(!Objects.equals(get(k),old)||(old==null&&!containsKey(k)))return false;put(k,v);return true;} default V replace(K k,V v){return containsKey(k)?put(k,v):null;} default void forEach(BiConsumer<? super K,? super V> a){for(Entry<K,V> e:entrySet())a.accept(e.getKey(),e.getValue());} default void replaceAll(BiFunction<? super K,? super V,? extends V> f){for(Entry<K,V> e:entrySet())e.setValue(f.apply(e.getKey(),e.getValue()));} default V computeIfAbsent(K k,Function<? super K,? extends V> f){V v=get(k);if(v==null){v=f.apply(k);if(v!=null)put(k,v);}return v;} default V computeIfPresent(K k,BiFunction<? super K,? super V,? extends V> f){V v=get(k);if(v!=null){v=f.apply(k,v);if(v==null)remove(k);else put(k,v);}return v;} default V compute(K k,BiFunction<? super K,? super V,? extends V> f){V old=get(k),v=f.apply(k,old);if(v==null){if(old!=null||containsKey(k))remove(k);}else put(k,v);return v;} default V merge(K k,V v,BiFunction<? super V,? super V,? extends V> f){Objects.requireNonNull(v);V old=get(k),n=old==null?v:f.apply(old,v);if(n==null)remove(k);else put(k,n);return n;} }
